func (this *Kucoin) HandleUtaFundingRate(client any, message map[string]any) {
	//
	//     {
	//         "T": "funding-fee",
	//         "P": "1782831961172694254",
	//         "d": {
	//             "s": "ETHUSDTM",
	//             "fr": "0.000035",
	//             "ft": 1782806400000,
	//             "nt": 1782835200000,
	//             "gl": 28800000,
	//             "fc": "0.00375",
	//             "ff": "-0.00375"
	//         }
	//     }
	//
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "d", map[string]any{}))
	var fundingRate any = this.ParseWsFundingRate(data)
	var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(fundingRate, "symbol"))
	if symbol != nil {
		ccxt.AddElementToObject(this.FundingRates, symbol, fundingRate)
	}
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add("fundingRate:", symbol))
	client.(ccxt.ClientInterface).Resolve(fundingRate, messageHash)
}
func (this *Kucoin) ParseWsFundingRate(data map[string]any, optionalArgs ...any) any {
	//
	//     {
	//         "s": "ETHUSDTM",
	//         "fr": "0.000035",
	//         "ft": 1782806400000,
	//         "nt": 1782835200000,
	//         "gl": 28800000,
	//         "fc": "0.00375",
	//         "ff": "-0.00375"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var fundingTimestamp *int64 = this.SafeInteger(data, "ft")
	var nextFundingTimestamp *int64 = this.SafeInteger(data, "nt")
	var marketId *string = this.SafeString(data, "s")
	var granularity *string = this.SafeString(data, "gl")
	return map[string]any{
		"info":                     data,
		"symbol":                   this.SafeSymbol(marketId, market, nil, "contract"),
		"markPrice":                nil,
		"indexPrice":               nil,
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                nil,
		"datetime":                 nil,
		"fundingRate":              this.SafeNumber(data, "fr"),
		"fundingTimestamp":         fundingTimestamp,
		"fundingDatetime":          this.Iso8601(fundingTimestamp),
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nextFundingTimestamp,
		"nextFundingDatetime":      this.Iso8601(nextFundingTimestamp),
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 this.ParseFundingInterval(granularity),
	}
}

